mapper.select:
SELECT * FROM mistakes

    user_id = #{userId, typeHandler=com.flittly.bankendspringboot.config.UUIDTypeHandler}
    AND category = #{category, typeHandler=com.flittly.bankendspringboot.config.CategoryTypeHandler}
    AND mastery_level = #{masteryLevel, typeHandler=com.flittly.bankendspringboot.config.MasteryLevelHandler}

ORDER BY added_at DESC
LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE mistakes
mastery_level = #{masteryLevel, typeHandler=com.flittly.bankendspringboot.config.MasteryLevelHandler}, question = #{question}, updated_at = NOW()
WHERE id = #{id, typeHandler=com.flittly.bankendspringboot.config.UUIDTypeHandler}
